def solve(g, verbose=False):
    n,bands=bands_of(g)
    H=len(g); W=len(g[0]); fc=g[0][0]
    sh=shapes_of(g,n)
    out=[[v for v in row[:n]] for row in g]
    # interior region per band: cols 1..n-2? for n=5, cols1..3
    used=[False]*len(sh)
    for bi,(r0,r1) in enumerate(bands):
        holes={(r,c) for r in range(r0,r1+1) for c in range(1,n-1) if g[r][c]==0}
        if not holes: 
            if verbose: print('band',(r0,r1),'empty'); continue
        cand=[]
        for si,(col,comp) in enumerate(sh):
            if used[si]: continue
            scells=set(comp)
            for tt in dihed(scells):
                tn=norm(tt)
                th=max(a for a,b in tn)+1; tw=max(b for a,b in tn)+1
                # interior cols 1..n-2 => offset dc in 1..n-2-tw+1, dr in r0..r1-th+1
                for dr in range(r0,r1-th+2):
                    for dc in range(1,n-tw):
                        cells={(dr+a+1,dc+b+1) for a,b in tn}
                        if holes<=cells and all(1<=r<=r1 and 1<=c<=n-2 and g[r][c]!=0 or (r,c) in holes for r,c in cells):
                            cand.append((si,col,dr,dc,tn,cells))
        if not cand:
            if verbose: print('band',(r0,r1),'NO COVER',sorted(holes))
            continue
        # prefer exact cover
        exact=[c for c in cand if c[5]==holes]
        chosen=exact if exact else max(cand,key=lambda c:len(c[5]&holes))
        used[chosen[0]]=True
        for hR,hC in chosen[5]:
            if g[hR][hC]==0: out[hR][hC]=chosen[1]
        if verbose: print('band',(r0,r1),'->color',chosen[1],'exact' if chosen[5]==holes else 'cover')
    return out
