def dihed(cells):
    # cells: list of (r,c) relative coords. 8 orientations via rotations/reflections, returned as normalized sets
    pts=[(r,c) for r,c in cells]
    res=set()
    import itertools
    for perm in itertools.product([1,-1],[0,1]):
        pass
    # rotate 4x flip
    def rotp(pts,k):
        for _ in range(k):
            pts=[(c,-r) for r,c in pts]
        return tuple(sorted(pts))
    orig=tuple(sorted(pts))
    for k in range(4):
        res.add(rotp(orig,k)); res.add(rotp([(r,-c) for r,c in orig],k))
    return [tuple(p) for p in res]

def normset(cells):
    r0=min(r for r,c in cells); c0=min(c for r,c in cells)
    return {(r-r0,c-c0) for r,c in cells}

def bands_of(g):
    H=len(g); W=len(g[0]); fc=g[0][0]
    seps=[r for r in range(H) if all(v==fc or v==0 for v in g[r])]
    bands=[]; prev=None
    for r in range(H):
        if r in set(seps):
            if prev is not None: bands.append((prev,r-1))
            prev=r
    if prev is not None: bands.append((prev+1,H-1))
    # also band before first sep
    if seps and 0<seps[0]: bands.insert(0,(0,seps[0]-1))
    return seps,bands

def shapes_of(g,n):
    H=len(g); W=len(g[0]); fc=g[0][0]
    seen=set(); sh=[]
    for r in range(H):
        for c in range(n,W):
            col=g[r][c]
            if col not in (fc,0) and (r,c) not in seen:
                st=[(r,c)]; comp=[]; seen.add((r,c))
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]==col and (na,nb) not in seen:
                            seen.add((na,nb)); st.append((na,nb))
                rs=[a for a,b in comp]; cs=[b for a,b in comp]
                m={(a-min(rs),b-min(cs)) for a,b in comp}
                variants=dihed(list(m))
                sh.append((col,variants))
    return sh

