    def lead(r_):
        c=0
        while c<len(g[r_]) and g[r_][c]==g[r_][0]: c+=1
        return c
    n=max(lead(r_) for r_ in range(H))
    barrows={r_ for r_ in range(H) if all(v==fc for v in g[r_][:n])}
    bands=[]; cur=None
    for r_ in range(H):
        if r_ in barrows:
            if cur is not None: bands.append(cur); cur=None
        else:
            if cur is None: cur=[r_]
            elif r_-cur[-1]==1: cur.append(r_)
    if cur is not None: bands.append(cur)
    templ=[]; seen=set()
    for r_ in range(H):
        for c_ in range(n,W):
            col=g[r_][c_]
            if col not in (fc,0) and (r_,c_) not in seen:
                st=[(r_,c_)]; comp=[]; seen.add((r_,c_))
                while st:
                    a,b=st.pop(); comp.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]==col and (na,nb) not in seen:
                            seen.add((na,nb)); st.append((na,nb))
                templ.append((col,tuple(sorted(comp))))
    out=[[v for v in row[:n]] for row in g]
    def norm(P):
        mr=min(p[0] for p in P); mc=min(p[1] for p in P)
        return tuple(sorted((p[0]-mr,p[1]-mc) for p in P))
    sigmap={}
    for i,(col,vl) in enumerate(templ): sigmap[norm(vl)]=(i,col)
    for b in bands:
        hitset={(hR,hC) for hR in range(b[0],b[-1]+1) for hC in range(1,n-1) if g[hR][hC]==0}
        hr=norm(hitset)
        if hr in sigmap:
            for hR,hC in hitset: out[hR][hC]=sigmap[hr][1]
    return out
